13	#endif
14	
15	// forward declarations
16	mi_decl_nodiscard static bool mi_check_padding_on_free(const mi_page_t* page, const mi_block_t* block, bool is_guarded, size_t* usable_size);
17	static size_t mi_page_usable_size_of(const mi_page_t* page, const mi_block_t* block, bool was_guarded);
18	static void   mi_stat_free(const mi_page_t* page, const mi_block_t* block);
19	// static bool   mi_check_is_double_free(const mi_page_t* page, const mi_block_t* block);
20	
21	
22	// ------------------------------------------------------
23	// Free
24	// ------------------------------------------------------
25	
26	// regular free of a (thread local) block pointer
27	// fast path written carefully to prevent spilling on the stack
28	static inline void mi_free_block_local(mi_page_t* page, mi_block_t* block, bool was_guarded, bool track_stats, bool check_full)
29	{
30	  // checks  
31	  size_t usable_size;
32	  if mi_unlikely(!mi_check_padding_on_free(page, block, was_guarded, &usable_size)) return; 
33	  // if mi_unlikely(!mi_check_is_double_free(page,block)) return;  // checked with padding
34	
35	  if (track_stats) { 
36	    mi_stat_free(page, block);    
37	    mi_track_free_size(block, usable_size); 
38	  }
39	  #if (MI_DEBUG>0) && !MI_TRACK_ENABLED  && !MI_TSAN
40	  const size_t dbgsize = (usable_size > MI_MiB ? MI_MiB : usable_size);
41	  _mi_memset_aligned(block, MI_DEBUG_FREED, dbgsize);  
42	  #endif
43	  
44	  // actual free: push on the local free list
45	  const mi_used_t used = page->used - 1;
46	  mi_block_set_next(page, block, page->local_free);
47	  page->used = used;
48	  page->local_free = block;
49	  if mi_unlikely(used==0) {  
50	    if (page->retire_expire==0) { // no need to re-retire retired pages (happens when we alloc/free one block repeatedly in an empty page)
51	      _mi_page_retire(page); 
52	    }
53	  }
54	  else if mi_unlikely(check_full && mi_page_is_in_full(page)) {
55	    _mi_page_unfull(page);
56	  }
57	}
58	
59	// Forward declaration for multi-threaded collect
60	static void mi_decl_noinline mi_free_try_collect_mt(mi_page_t* page, mi_block_t* mt_free) mi_attr_noexcept;
61	
62	// Free a block multi-threaded
63	static inline void mi_free_block_mt(mi_page_t* page, mi_block_t* block, bool was_guarded, bool allow_collect) mi_attr_noexcept
64	{
65	  size_t usable_size;
66	  if mi_unlikely(!mi_check_padding_on_free(page, block, was_guarded, &usable_size)) return;    // checking padding is safe for mt
67	  
68	  // adjust stats (after padding check )
69	  mi_stat_free(page, block);    // stat_free may access the padding
70	  mi_track_free_size(block, usable_size);
71	
72	  // _mi_padding_shrink(page, block, sizeof(mi_block_t));
73	  #if (MI_DEBUG>0) && !MI_TRACK_ENABLED  && !MI_TSAN       // note: when tracking, cannot use mi_usable_size with multi-threading
74	  if (!was_guarded) {
75	    const size_t dbgsize = (usable_size > MI_MiB ? MI_MiB : usable_size);
76	    _mi_memset_aligned(block, MI_DEBUG_FREED, dbgsize);
77	  }
78	  #endif
79	
80	  // push atomically on the page thread free list
81	  mi_thread_free_t tf_new;
82	  mi_thread_free_t tf_old = mi_atomic_load_relaxed(&page->xthread_free);
83	  do {
84	    mi_block_set_next(page, block, mi_tf_block(tf_old));
85	    const bool new_owned = (allow_collect ? true : mi_tf_is_owned(tf_old));    // if allow collection then always try to claim it if the page is abandoned 
86	    tf_new = mi_tf_create(block, new_owned);
87	  } while (!mi_atomic_cas_weak_acq_rel(&page->xthread_free, &tf_old, tf_new)); // todo: release is enough?
88	
89	  // and atomically try to collect the page if it was abandoned
90	  if (allow_collect) {
91	    const bool is_owned_now = !mi_tf_is_owned(tf_old);
92	    if (is_owned_now) {
93	      mi_assert_internal(mi_page_is_abandoned(page));
94	      mi_free_try_collect_mt(page,block);
95	    }
96	  }
97	}
98	
99	
100	// Adjust a block that was allocated aligned, to the actual start of the block in the page.
101	// note: this can be called from `mi_free_generic_mt` where a non-owning thread accesses the
102	// `page_woffset` and `block_size` fields; however these are constant and the page won't be
103	// deallocated (as the block we are freeing keeps it alive) and thus safe to read concurrently.
104	mi_block_t* _mi_page_ptr_unalign(const mi_page_t* page, const void* p) {
105	  mi_assert_internal(page!=NULL && p!=NULL);
106	
107	  const size_t diff = (uint8_t*)p - mi_page_start(page);
108	  const size_t block_size = mi_page_block_size(page);
109	  size_t adjust = diff & (block_size - 1); 
110	  if mi_unlikely(!_mi_is_power_of_two(block_size)) {
111	    adjust = diff % block_size;     
112	  }
113	  return (mi_block_t*)((uintptr_t)p - adjust);
114	}
115	
116	static inline mi_block_t* mi_validate_block_from_ptr( const mi_page_t* page, const void* p ) {
117	  mi_assert(_mi_page_ptr_unalign(page,p) == (mi_block_t*)p); // should never be an interior pointer
118	  #if MI_SECURE > 0
119	  // in secure mode we always unalign to guard against free-ing interior pointers
120	  return _mi_page_ptr_unalign(page,p);
121	  #else
122	  MI_UNUSED(page);
123	  return (mi_block_t*)p;
124	  #endif
125	}
126	
127	// forward declaration for a MI_GUARDED build
128	#if MI_GUARDED
129	static void mi_block_unguard(mi_page_t* page, mi_block_t* block, void* p); // forward declaration
130	static inline bool mi_block_check_unguard(mi_page_t* page, mi_block_t* block, void* p) {
131	  if (mi_block_ptr_is_guarded(block, p)) { 
132	    mi_block_unguard(page, block, p); 
133	    return true;
134	  }
135	  else {
136	    return false;
137	  }
138	}
139	#else
140	static inline bool mi_block_check_unguard(mi_page_t* page, mi_block_t* block, void* p) {
141	  MI_UNUSED(page); MI_UNUSED(block); MI_UNUSED(p);
142	  return false;
143	}
144	#endif
145	
146	
147	// free a local pointer  (page parameter comes first for better codegen)
148	static void mi_decl_noinline mi_free_generic_local(mi_page_t* page, void* p) mi_attr_noexcept {
149	  mi_assert_internal(p!=NULL && page != NULL);
150	  mi_block_t* const block = (mi_page_has_interior_pointers(page) ? _mi_page_ptr_unalign(page, p) : mi_validate_block_from_ptr(page,p));
151	  const bool was_guarded = mi_block_check_unguard(page, block, p);
152	  mi_free_block_local(page, block, was_guarded, true /* track stats */, true /* check for a full page */);
153	}
154	
155	// free a pointer owned by another thread (page parameter comes first for better codegen)
156	static void mi_decl_noinline mi_free_generic_mt(mi_page_t* page, void* p, bool allow_collect) mi_attr_noexcept {
157	  mi_assert_internal(p!=NULL && page != NULL);
158	  mi_block_t* const block = (mi_page_has_interior_pointers(page) ? _mi_page_ptr_unalign(page, p) : mi_validate_block_from_ptr(page,p));
159	  const bool was_guarded = mi_block_check_unguard(page, block, p);
160	  mi_free_block_mt(page, block, was_guarded, allow_collect);

