8	/* ----------------------------------------------------------------------------
9	"Arenas" are fixed area's of OS memory from which we can allocate
10	large blocks (>= MI_ARENA_MIN_BLOCK_SIZE, 64KiB).
11	In contrast to the rest of mimalloc, the arenas are shared between
12	threads and need to be accessed using atomic operations.
13	
14	Arenas are also used to for huge OS page (1GiB) reservations or for reserving
15	OS memory upfront which can be improve performance or is sometimes needed
16	on embedded devices. We can also employ this with WASI or `sbrk` systems
17	to reserve large arenas upfront and be able to reuse the memory more effectively.
18	
19	The arena allocation needs to be thread safe and we use an atomic bitmap to allocate.
20	-----------------------------------------------------------------------------*/
21	
22	#include "mimalloc.h"
23	#include "mimalloc/internal.h"
24	#include "mimalloc/prim-tls.h"
25	#include "bitmap.h"
26	
27	
28	/* -----------------------------------------------------------
29	  Arena id's
30	----------------------------------------------------------- */
31	
32	mi_arena_id_t _mi_arena_id_none(void) {
33	  return NULL;
34	}
35	
36	mi_arena_t* _mi_arena_from_id(mi_arena_id_t id) {
37	  mi_arena_t* const arena = (mi_arena_t*)id;
38	  mi_assert_internal(arena==NULL || arena->parent==NULL); // id's should never point to sub-arena's
39	  return arena;
40	}
41	
42	mi_arena_id_t mi_arena_id_from_arena(mi_arena_t* arena) {
43	  mi_assert_internal(arena==NULL || arena->parent==NULL);
44	  return (arena==NULL ? _mi_arena_id_none() : (mi_arena_id_t)arena);
45	}
46	
47	
48	static bool mi_arena_is_suitable(mi_arena_t* arena, mi_arena_t* req_arena) {
49	  if (arena == req_arena) return true;                         // they match
50	  if (arena == NULL) return false;
51	  if (req_arena == NULL && !arena->is_exclusive) return true;  // or the arena is not exclusive, and we didn't request a specific one
52	  if (arena->parent != NULL && arena->parent == req_arena) return true;  // sub-arena? (note that req_arena is never a sub arena)
53	  return false;
54	}
55	
56	bool _mi_arena_memid_is_suitable(mi_memid_t memid, mi_arena_t* request_arena) {
57	  if (memid.memkind == MI_MEM_ARENA) {
58	    return mi_arena_is_suitable(memid.mem.arena.arena, request_arena);
59	  }
60	  else {
61	    return mi_arena_is_suitable(NULL, request_arena);
62	  }
63	}
64	
65	size_t mi_arenas_get_count(mi_subproc_t* subproc) {
66	  return mi_atomic_load_relaxed(&subproc->arena_count);
67	}
68	
69	mi_arena_t* mi_arena_from_index(mi_subproc_t* subproc, size_t idx) {
70	  mi_assert_internal(idx < mi_arenas_get_count(subproc));
71	  return mi_atomic_load_ptr_acquire(mi_arena_t, &subproc->arenas[idx]);
72	}
73	
74	static size_t mi_arena_info_slices(mi_arena_t* arena) {
75	  return arena->info_slices;
76	}
77	
78	#if MI_DEBUG > 1
79	static bool mi_heap_has_page(mi_heap_t* heap, mi_arena_t* arena, mi_page_t* page) {
80	  mi_assert(arena->arena_idx < MI_MAX_ARENAS);
81	  mi_arena_pages_t* arena_pages = heap->arena_pages[arena->arena_idx];
82	  return (page->memid.memkind == MI_MEM_ARENA &&
83	          page->memid.mem.arena.arena == arena &&
84	          arena_pages != NULL &&
85	          mi_bitmap_is_setN(arena_pages->pages, page->memid.mem.arena.slice_index, 1));
86	}
87	#endif
88	
89	size_t mi_arena_min_alignment(void) {
90	  return MI_ARENA_ALIGNMENT;
91	}
92	
93	size_t mi_arena_min_size(void) {
94	  return MI_ARENA_MIN_SIZE;
95	}
96	
97	// slices reserved for page meta info at the start of aligned chunks
